// Types for the `hinny` package. Written by hand; `native.d.ts` (generated by `napi build`) has
// the native module's bare signatures.

/**
 * A document key, or a version: an unsigned 64-bit integer. Pass a safe integer (up to
 * 2^53 - 1) or a bigint (up to 2^64 - 1); keys and versions always come back as bigints, so
 * none is ever rounded.
 */
export type Key = number | bigint

/**
 * An attribute's value. In: an integer-valued number (or a bigint, or a boolean as 0 or 1) is
 * an integer, any other number a float. Out: integers are numbers when they are safe integers
 * and bigints when they aren't, floats are numbers, strings are strings, and tags (several
 * strings: a set) are an array of strings, each once and in order.
 */
export type AttrValue = number | bigint | string | string[]

/** A vector: a Float32Array (copied once), a Float64Array, or an array of numbers. */
export type Vector = Float32Array | Float64Array | readonly number[]

/** Terms with weights (from a learned sparse model): term → weight, or [term, weight] pairs. */
export type Terms = Readonly<Record<string, number>> | ReadonlyArray<readonly [string, number]>

/**
 * The `code` of an error the module throws:
 * - `ERR_HINNY_INVALID`: the input is wrong (a field or attribute not in the schema, a vector of
 *   other dimensions, NaN in a float attribute, an unknown option, a batch over the limit).
 * - `ERR_HINNY_TIMEOUT`: a query ran past its `timeout`.
 * - `ERR_HINNY_LOCKED`: the namespace is open for writing elsewhere (another process, or another
 *   handle in this one).
 * - `ERR_HINNY_CLOSED`: the namespace, snapshot or database was closed.
 * - `ERR_HINNY_IO`: reading or writing files failed.
 */
export type ErrorCode = 'ERR_HINNY_INVALID' | 'ERR_HINNY_TIMEOUT' | 'ERR_HINNY_LOCKED' | 'ERR_HINNY_CLOSED' | 'ERR_HINNY_IO'

/** How a namespace's vectors are compared. */
export type Metric = 'cosine' | 'euclidean' | 'dot'

/** What a namespace's documents hold. Every part is optional. */
export interface Schema {
  /** Text fields, searched with BM25: a name, names, or name → boost (1 by default). */
  text?: string | readonly string[] | Readonly<Record<string, number>>
  /** Sparse fields: terms with weights from a learned sparse model, scored by dot product. */
  sparse?: readonly string[]
  /** Integer attributes. */
  ints?: readonly string[]
  /** Float attributes (a score, a price, a coordinate). An integer given for one is that number. */
  floats?: readonly string[]
  /** String attributes. */
  strings?: readonly string[]
  /** Attributes of several strings (labels, owners): given as an array, filtered with `attr(name).has(tag)`. */
  tags?: readonly string[]
  /** The vectors' dimensions. */
  vector?: number
  /**
   * How vectors are compared, the one the embedding model was trained for: 'cosine' (the
   * default), 'euclidean' or 'dot'. Fixed once set: opening the namespace with another throws
   * `ERR_HINNY_INVALID`. A hit's vector score is higher for a nearer vector under each: the
   * cosine, the squared distance negated (0 for the query itself), the dot product. Under
   * 'euclidean' and 'dot' vectors are kept as given, not normalized.
   */
  metric?: Metric
  /** Keep the text, for hits' `text` and snippets (default true). */
  storeText?: boolean
  /**
   * Stem the text fields in this language ("english", "german", … 18 in all) and drop its
   * stopwords. Fixed once the namespace holds data. Default: words as written.
   */
  language?: string
  /** With `language`: drop its stopwords (default true). */
  stopwords?: boolean
}

/** The schema of an open namespace (`ns.schema`). */
export interface SchemaInfo {
  /** Text field → boost. */
  text: Record<string, number>
  sparse: string[]
  ints: string[]
  floats: string[]
  strings: string[]
  tags: string[]
  vector: number | null
  /** How its vectors are compared; null without a vector. */
  metric: Metric | null
  storeText: boolean
}

/** What to change of a document that is there (`ns.patch`): every part is optional. */
export interface Patch {
  /** Text fields to replace: field → text. */
  text?: Readonly<Record<string, string>>
  /** Attributes to replace: name → value (an array for tags). Undefined and null values are left out. */
  attrs?: Readonly<Record<string, AttrValue | readonly string[] | boolean | null | undefined>>
  /** A new vector. */
  vector?: Vector
  /**
   * Sparse fields to replace: field → terms. A sparse field's terms aren't kept as they were
   * given, so in a namespace with sparse fields a patch gives each one's terms again here or
   * names the field in `remove`; one that does neither throws `ERR_HINNY_INVALID`.
   */
  sparse?: Readonly<Record<string, Terms>>
  /** A new version (otherwise it stays what it was). */
  version?: Key
  /** Names of attributes or text fields to take away. */
  remove?: readonly string[]
}

/** A document to write. */
export interface Document {
  key: Key
  /** A string (for a schema with one text field), or field → text. */
  text?: string | Readonly<Record<string, string>>
  /** Attribute → value. Undefined and null values are left out. */
  attrs?: Readonly<Record<string, AttrValue | readonly string[] | boolean | null | undefined>>
  vector?: Vector
  /** For syncing: `versions()` gives it back (default 0). */
  version?: Key
  /** Sparse field → terms with weights. */
  sparse?: Readonly<Record<string, Terms>>
}

export interface QueryOptions {
  /** Full text (BM25). */
  text?: string
  /** Nearest neighbours, by the namespace's metric. With `text`, a hybrid query, fused into one ranking. */
  vector?: Vector
  /** Sparse field → terms with weights, scored by dot product. */
  sparse?: Readonly<Record<string, Terms>>
  /** Applies to every retriever. Without text, a vector or sparse terms, lists documents by it. */
  filter?: Filter
  /** Default 10. */
  limit?: number
  /** An attribute to order by, "-name" for largest first (instead of by score). */
  orderBy?: string
  /** Only documents with every word of `text`. */
  allWords?: boolean
  /**
   * The text's last word is still being typed (a search box): it also matches the `typing` most
   * common words that start with it (32 is plenty), so "tax ret" finds "tax return". 0 (the
   * default): a finished word.
   */
  typing?: number
  /** Vector clusters each segment probes (0, the default: each segment's calibrated budget). */
  nprobe?: number
  /** Snippet length in characters (default 240; 0 for none). */
  snippet?: number
  /** Whether hits carry their whole stored text (default true). */
  withText?: boolean
  /** Hybrid: the weight of BM25 against cosine, each scaled to 0–1 (default 0.5). */
  textWeight?: number
  /** Hybrid: "convex" (scaled scores, weighted; the default) or "rrf" (reciprocal rank fusion). */
  fusion?: 'convex' | 'rrf'
  /** How many each retriever of a hybrid query finds before fusion (0: the defaults). */
  textCandidates?: number
  vectorCandidates?: number
  sparseCandidates?: number
  /** Milliseconds before the query gives up with ERR_HINNY_TIMEOUT (never partial results). */
  timeout?: number
}

/** A result. */
export interface Hit {
  key: bigint
  /** BM25, the vector score (by the namespace's metric), or the fused score. */
  score: number
  /** The text (or sparse) retriever's score, if it found this document. */
  textScore: number | null
  /** The vector retriever's score, if it found this document. */
  vectorScore: number | null
  attrs: Record<string, AttrValue>
  /** Stored text by field (empty with `withText: false`, or a schema with `storeText: false`). */
  text: Record<string, string>
  /** The best-matching part of the best-matching field, about `snippet` characters. */
  snippet: string | null
  snippetField: string | null
  /** [start, end] of the query's words in `snippet`, in UTF-16 units: `snippet.slice(start, end)`. */
  highlights: Array<[number, number]>
}

/** What one retriever of a hybrid query found before fusion. */
export interface Retrieved {
  /** How many it was asked for. */
  depth: number
  found: number
  /** [lowest, highest] score, or null if it found none. */
  scores: [number, number] | null
}

export interface Explained {
  hits: Hit[]
  /** For a hybrid query, how it was fused; null otherwise. */
  fusion: { lexical: Retrieved; vector: Retrieved; both: number; fused: number } | null
}

/** What `verify` read. */
export interface Verified {
  /** Segments read against their checksums. */
  segments: number
  /** Segments written before there were checksums (`optimize` rewrites them). */
  uncheckedSegments: number
  /** Files of stored text read. */
  textFiles: number
}

export interface Stats {
  documents: number
  segments: number
  inMemory: number
  merging: boolean
  flushing: boolean
  memtableBytes: number
  logBytes: number
  pinnedSegments: number
  pinnedBytes: number
  vectorCaches: number
  vectorCacheBytes: number
  keptFilters: number
  keptFilterBytes: number
  vectorGenerations: number
  vectorClusters: number
}

export interface Limits {
  /** The largest batch accepted, in bytes as logged (default 1 GiB). */
  maxBatchBytes?: number
  /** Bytes in memory before a flush (default 256 MiB). */
  flushBytes?: number
}

/** A condition on attributes: `attr("year").gte(2025)`. */
export declare class Filter {
  private constructor()
  /** Both this and `other`. */
  and(other: Filter): Filter
  /** This or `other`, or both. */
  or(other: Filter): Filter
  /** Everything this filter doesn't pass. */
  not(): Filter
  toString(): string
}

/** An attribute to filter on. Numbers in conditions are integers or floats, whichever the attribute is. */
export declare class Attr {
  private constructor()
  /** Equal to `value`. On tags: one of them is (the same as `has`). */
  eq(value: number | bigint | string | boolean): Filter
  ne(value: number | bigint | string | boolean): Filter
  gt(x: number | bigint): Filter
  gte(x: number | bigint): Filter
  lt(x: number | bigint): Filter
  lte(x: number | bigint): Filter
  /** From `low` to `high`, both included. */
  between(low: number | bigint, high: number | bigint): Filter
  oneOf(values: ReadonlyArray<number | bigint | string | boolean>): Filter
  /** A tags attribute has this tag. */
  has(tag: string): Filter
  /** A tags attribute has at least one of these. */
  hasAny(tags: readonly string[]): Filter
  /** A tags attribute has every one of these. */
  hasAll(tags: readonly string[]): Filter
  /** Starts with `prefix` (ignoring case). On tags: one of them does. */
  prefix(prefix: string): Filter
  /** Contains the characters `part` (ignoring case). On tags: one of them does; for "has this tag", `has`. */
  contains(part: string): Filter
  /** The whole string matches the pattern: `*` is any run of characters, `?` any one, a backslash takes the next as itself. On tags: one of them does. */
  glob(pattern: string): Filter
  /** `glob`, whatever the case. */
  iglob(pattern: string): Filter
  /** The attribute has a value. */
  exists(): Filter
  toString(): string
}

/** An attribute to filter on: `attr("kind").eq("pdf")`. */
export declare function attr(name: string): Attr

/** A stable key for a string id (FNV-1a, 63 bits), the same as Python's `hinny.key` and C's `hinny_key`. */
export declare function key(id: string): bigint

/** A directory of namespaces. */
export declare class Database {
  /** Opens the database in a directory, creating it if there is none. */
  constructor(path: string)
  readonly path: string
  /**
   * Opens a namespace, or creates it with this schema. A schema can grow: more text fields at
   * the end, more attributes, a vector if it had none. One handle per namespace at a time: open
   * it again only after `close()`.
   */
  namespace(name: string, schema?: Schema): Namespace
  /**
   * Opens a namespace that exists, with the schema it has (`ns.schema` says what that is).
   * Throws if there is none of that name.
   */
  open(name: string): Namespace
  /** The namespaces in the directory. */
  namespaces(): string[]
  /**
   * Deletes a namespace and everything in it. It must not be open: `close()` its `Namespace`
   * first (that closes its snapshots too), or this throws ERR_HINNY_LOCKED and leaves it as it
   * is. A `flushAsync`, `optimizeAsync` or `verifyAsync` still running keeps it open until it
   * is done: await those first. Throws ERR_HINNY_IO if there is none of that name.
   */
  delete(name: string): void
  /** Closes every namespace opened from this database, and their snapshots. */
  close(): void
  [Symbol.dispose](): void
}

/** Documents sharing a schema. */
export declare class Namespace {
  private constructor()
  readonly name: string
  readonly schema: SchemaInfo
  /** The number of documents. */
  readonly size: number
  readonly closed: boolean
  /**
   * Adds a document, or replaces the one with its key. Searchable on return, and recoverable
   * after a process crash; `sync()` for an OS crash or power loss too.
   */
  upsert(doc: Document): void
  /** Documents as one batch: all or none of them, and no query sees part of it. Returns how many. */
  upsertMany(docs: Iterable<Document>): number
  /** Upserts and deletes as one batch: all or none of it. Returns how many changes. */
  apply(changes: { upsert?: Iterable<Document>; delete?: Iterable<Key> }): number
  /** Deletes a document (nothing happens if there is none). */
  delete(key: Key): void
  /** Deletes these keys as one batch. Returns how many. */
  deleteMany(keys: Iterable<Key>): number
  /** A document's attributes, or null if there is no document with that key. */
  get(key: Key): Record<string, AttrValue> | null
  /** A document's stored text, field → text, or null. */
  text(key: Key): Record<string, string> | null
  /** Key → version, for syncing only what changed. */
  versions(): Map<bigint, bigint>
  /**
   * Changes part of the document with a key and keeps the rest: the text fields, attributes,
   * sparse fields and vector in `patch` are replaced, the names in `remove` taken away. With `condition`, only if
   * the document passes it (checked and written together). Returns false, writing nothing, if
   * there is no such document or it doesn't pass. The document is read and written again whole,
   * so a patch costs what an upsert does, and it needs the text to have been stored.
   */
  patch(key: Key, patch: Patch, condition?: Filter): boolean
  /** `patch` for every document that passes `filter` now; returns how many that was. */
  patchWhere(filter: Filter, patch: Patch): number
  /**
   * `upsert`, unless there is a document with this key that doesn't pass `condition`: written
   * if there is none yet, or if the one there passes (say a revision below the new one). Checked
   * and written together, so two writers that both read revision 4 can't both write revision 5.
   * Returns whether it was written.
   */
  upsertIf(doc: Document, condition: Filter): boolean
  /** `delete`, only if the document exists and passes `condition`. Returns whether it was deleted. */
  deleteIf(key: Key, condition: Filter): boolean
  /** How many documents pass `filter` (every document, without one). */
  count(filter?: Filter): number
  /**
   * Deletes every document that passes `filter` now, and returns how many that was: a user's
   * (`attr('user').eq(id)`), the expired (`attr('at').lt(cutoff)`). All of them or, on an
   * error, none.
   */
  deleteWhere(filter: Filter): number
  /**
   * How many documents have each value of `attr`, among those that pass `filter`: the most
   * frequent first, at most `limit` (0, the default: every value).
   */
  countBy(attr: string, filter?: Filter | null, limit?: number): Array<[number | bigint | string, number]>
  /** Searches: text, a vector, sparse terms, or any of them together (hybrid). */
  query(options?: QueryOptions): Hit[]
  /** As `query`, with how a hybrid query fused what each retriever found. */
  explain(options?: QueryOptions): Explained
  /** The namespace as of now: reads on it see exactly the writes before it, for as long as it's kept. */
  snapshot(): Snapshot
  /** Synchronizes earlier writes to storage, without building segments. */
  sync(): void
  /**
   * A namespace of its own, named `name` in the same database, holding what this one holds
   * now: a sandbox to try something on real data. The two are apart from then on. Takes
   * milliseconds whatever the size, and no more disk until they differ (its files are links
   * to this one's). Throws ERR_HINNY_INVALID if there is a namespace of that name.
   */
  fork(name: string): Namespace
  /** Synchronizes writes and writes memory as a segment (which also happens on its own). */
  flush(): void
  /** Flushes and merges everything into one segment: the fastest layout, after a bulk load. */
  optimize(): void
  /** Reads every file against its checksums; throws ERR_HINNY_IO naming the first damaged one. */
  verify(): Verified
  /** `flush` on libuv's thread pool, keeping the event loop free. */
  flushAsync(): Promise<void>
  /** `optimize` on libuv's thread pool: it can take seconds on a large namespace. */
  optimizeAsync(): Promise<void>
  /** `verify` on libuv's thread pool: it reads every file. */
  verifyAsync(): Promise<Verified>
  stats(): Stats
  /** Sets the writer's limits; omitted ones stay as they are. */
  setLimits(limits: Limits): void
  /**
   * Lets go of the namespace and its snapshots, releasing its directory's lock once a running
   * async call is done. Later calls throw ERR_HINNY_CLOSED.
   */
  close(): void
  [Symbol.dispose](): void
}

/** The namespace as of one moment (`Namespace.snapshot()`). */
export declare class Snapshot {
  private constructor()
  /** The sequence number of the newest batch it includes. */
  readonly seq: bigint
  query(options?: QueryOptions): Hit[]
  explain(options?: QueryOptions): Explained
  get(key: Key): Record<string, AttrValue> | null
  text(key: Key): Record<string, string> | null
  versions(): Map<bigint, bigint>
  count(filter?: Filter): number
  countBy(attr: string, filter?: Filter | null, limit?: number): Array<[number | bigint | string, number]>
  /** Lets go of the snapshot, so the segments only it held can be removed. */
  close(): void
  [Symbol.dispose](): void
}
